import html
import logging
import re
from dataclasses import dataclass, field
from typing import Any

from .http_client import NotFound, PoliteClient

log = logging.getLogger("metacritic")

BACKEND = "https://backend.metacritic.com"
SITE = "https://www.metacritic.com"
IMG_PREFIX = f"{SITE}/a/img/catalog"

PLATFORM_SHORT = {
    "playstation-5": "PS5",
    "playstation-4": "PS4",
    "playstation-3": "PS3",
    "nintendo-switch-2": "NS2",
    "nintendo-switch": "NS",
    "xbox-series-x": "XSX",
    "xbox-one": "XONE",
    "xbox-360": "X360",
    "pc": "PC",
    "ios-iphoneipad": "iOS",
    "meta-quest": "Quest",
    "3ds": "3DS",
    "wii-u": "Wii U",
    "playstation-vita": "Vita",
}


def platform_short(slug: str | None, name: str | None) -> str:
    if slug and slug in PLATFORM_SHORT:
        return PLATFORM_SHORT[slug]
    return name or slug or "?"


def platform_slugify(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")


def cover_url(bucket_path: str | None) -> str | None:
    if not bucket_path:
        return None
    return IMG_PREFIX + bucket_path


@dataclass
class ListItem:
    id: int
    slug: str
    title: str
    release_date: str | None = None
    metascore: int | None = None
    cover_url: str | None = None
    lead_platform: str | None = None
    genres: list[str] = field(default_factory=list)


@dataclass
class Review:
    kind: str
    sentiment: str
    quote: str
    score: float | None = None
    author: str | None = None
    url: str | None = None
    date: str | None = None
    platform: str | None = None

    def to_dict(self) -> dict:
        return self.__dict__.copy()


@dataclass
class PlatformInfo:
    slug: str
    name: str
    short: str
    is_lead: bool = False
    metascore: int | None = None
    critic_count: int | None = None
    userscore: float | None = None
    user_count: int | None = None
    release_date: str | None = None


@dataclass
class GameDetails:
    id: int
    slug: str
    title: str
    description: str | None = None
    release_date: str | None = None
    rating: str | None = None
    developers: list[str] = field(default_factory=list)
    publishers: list[str] = field(default_factory=list)
    genres: list[str] = field(default_factory=list)
    franchises: list[str] = field(default_factory=list)
    cover_url: str | None = None
    hero_url: str | None = None
    video_embed_url: str | None = None
    video_manifest_url: str | None = None
    video_title: str | None = None
    lead_platform: str | None = None
    platforms: list[PlatformInfo] = field(default_factory=list)
    critic_reviews: list[Review] = field(default_factory=list)
    user_reviews: list[Review] = field(default_factory=list)
    critic_total: int = 0
    user_total: int = 0
    lead_userscore: float | None = None
    lead_user_count: int | None = None
    critic_negative_count: int = 0
    user_negative_count: int = 0

    @property
    def metascore(self) -> int | None:
        lead = next((p for p in self.platforms if p.is_lead and p.metascore is not None), None)
        if lead:
            return lead.metascore
        scores = [p.metascore for p in self.platforms if p.metascore is not None]
        return max(scores) if scores else None

    @property
    def userscore(self) -> float | None:
        lead = next((p for p in self.platforms if p.is_lead and p.userscore is not None), None)
        if lead:
            return lead.userscore
        scores = [p.userscore for p in self.platforms if p.userscore is not None]
        return max(scores) if scores else None


def _int_or_none(v: Any) -> int | None:
    try:
        return int(v) if v is not None else None
    except (TypeError, ValueError):
        return None


def _float_or_none(v: Any) -> float | None:
    try:
        return float(v) if v is not None else None
    except (TypeError, ValueError):
        return None


def parse_list(payload: dict) -> tuple[list[ListItem], int]:
    data = (payload or {}).get("data") or {}
    items = []
    for raw in data.get("items") or []:
        if not raw or raw.get("id") is None or not raw.get("slug"):
            continue
        plats = raw.get("platforms") or []
        items.append(
            ListItem(
                id=int(raw["id"]),
                slug=raw["slug"],
                title=(raw.get("title") or raw["slug"]).strip(),
                release_date=raw.get("releaseDate"),
                metascore=_int_or_none((raw.get("criticScoreSummary") or {}).get("score")),
                cover_url=cover_url((raw.get("image") or {}).get("bucketPath")),
                lead_platform=plats[0].get("name") if plats else None,
                genres=[g.get("name") for g in raw.get("genres") or [] if g.get("name")],
            )
        )
    return items, int(data.get("totalResults") or 0)


def components_by_name(payload: dict) -> dict[str, dict]:
    out = {}
    for comp in (payload or {}).get("components") or []:
        name = (comp.get("meta") or {}).get("componentName")
        if name:
            out[name] = comp
    return out


def clean_text(text: str | None) -> str | None:
    if text is None:
        return None
    text = html.unescape(text).replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip() or None


def _pick_image(images: list[dict], *types: str) -> str | None:
    for t in types:
        for img in images or []:
            if img.get("typeName") == t and img.get("bucketPath"):
                return cover_url(img["bucketPath"])
    return None


def parse_reviews(summary_component: dict | None, kind: str) -> tuple[list[Review], int]:
    if not summary_component or "data" not in summary_component:
        return [], 0
    data = summary_component.get("data") or {}
    item = data.get("item") or {}
    seen: set[str] = set()
    out: list[Review] = []
    for sentiment in ("positive", "neutral", "negative", "default"):
        for r in item.get(sentiment) or []:
            rev = _review_from_raw(r, kind, sentiment)
            if rev and rev.quote not in seen:
                seen.add(rev.quote)
                out.append(rev)
    return out, int(data.get("totalResults") or 0)


def sentiment_for(kind: str, score: float | None) -> str:
    if score is None:
        return "neutral"
    if kind == "critic":
        return "positive" if score >= 75 else "negative" if score < 50 else "neutral"
    return "positive" if score >= 7.5 else "negative" if score < 5 else "neutral"


PLACEHOLDER_QUOTES = ("quotation forthcoming", "quote not yet available")


def _review_from_raw(r: dict, kind: str, sentiment: str | None) -> Review | None:
    quote = clean_text(r.get("quote"))
    if not quote or quote.lower().startswith(PLACEHOLDER_QUOTES):
        return None
    score = _float_or_none(r.get("score"))
    if sentiment in (None, "default"):
        sentiment = sentiment_for(kind, score)
    author = r.get("publicationName") if kind == "critic" else r.get("author")
    return Review(
        kind=kind,
        sentiment=sentiment,
        quote=quote,
        score=score,
        author=author or None,
        url=r.get("url") if kind == "critic" else None,
        date=r.get("date"),
        platform=r.get("platform"),
    )


def parse_review_list(payload: dict, kind: str) -> tuple[list[Review], int]:
    data = (payload or {}).get("data") or {}
    out = []
    for r in data.get("items") or []:
        rev = _review_from_raw(r, kind, None)
        if rev:
            out.append(rev)
    return out, int(data.get("totalResults") or 0)


def parse_user_stats(payload: dict) -> tuple[float | None, int | None]:
    item = ((payload or {}).get("data") or {}).get("item") or {}
    count = _int_or_none(item.get("reviewCount")) or 0
    score = _float_or_none(item.get("score"))
    if not count or not score:
        return None, count or 0
    return score, count


def parse_composer(payload: dict) -> GameDetails:
    comps = components_by_name(payload)
    product = comps.get("product")
    if not product or "data" not in product:
        raise NotFound("product component missing")
    item = product["data"].get("item") or {}
    companies = (item.get("production") or {}).get("companies") or []
    video = item.get("video") or {}
    lead_name = item.get("platform")

    platforms: list[PlatformInfo] = []
    for p in item.get("platforms") or []:
        name = p.get("name") or ""
        slug = p.get("slug") or platform_slugify(name)
        css = p.get("criticScoreSummary") or {}
        platforms.append(
            PlatformInfo(
                slug=slug,
                name=name,
                short=platform_short(slug, name),
                is_lead=bool(p.get("isLeadPlatform")) or (name == lead_name and not any(
                    q.get("isLeadPlatform") for q in item.get("platforms") or [])),
                metascore=_int_or_none(css.get("score")),
                critic_count=_int_or_none(css.get("reviewCount")),
                release_date=p.get("releaseDate"),
            )
        )
    platforms.sort(key=lambda p: (not p.is_lead, p.name))

    lead_userscore, lead_user_count = None, None
    user_negative = 0
    uss = comps.get("user-score-summary")
    if uss and "data" in uss:
        lead_userscore, lead_user_count = parse_user_stats(uss)
        user_negative = _int_or_none(((uss.get("data") or {}).get("item") or {}).get("negativeCount")) or 0
    critic_negative = 0
    css_comp = comps.get("critic-score-summary")
    if css_comp and "data" in css_comp:
        critic_negative = _int_or_none(((css_comp.get("data") or {}).get("item") or {}).get("negativeCount")) or 0
        for p in platforms:
            if p.is_lead:
                p.userscore, p.user_count = lead_userscore, lead_user_count

    critic_reviews, critic_total = parse_reviews(comps.get("critic-reviews"), "critic")
    user_reviews, user_total = parse_reviews(comps.get("user-reviews"), "user")

    return GameDetails(
        id=int(item.get("id")),
        slug=item.get("slug"),
        title=clean_text(item.get("title")) or item.get("slug"),
        description=clean_text(item.get("description")),
        release_date=item.get("releaseDate"),
        rating=item.get("rating"),
        developers=[c["name"] for c in companies if c.get("typeName") == "Developer" and c.get("name")],
        publishers=[c["name"] for c in companies if c.get("typeName") == "Publisher" and c.get("name")],
        genres=[g["name"] for g in item.get("genres") or [] if g.get("name")],
        franchises=[f["name"] for f in (item.get("gameTaxonomy") or {}).get("franchises") or [] if f.get("name")],
        cover_url=_pick_image(item.get("images"), "cardImage", "mainImage"),
        hero_url=_pick_image(item.get("images"), "mainImage", "cardImage"),
        video_embed_url=video.get("embedUrl"),
        video_manifest_url=video.get("manifestUrl"),
        video_title=clean_text(video.get("title") or video.get("videoTitle")),
        lead_platform=lead_name or next((p.name for p in platforms if p.is_lead), None),
        platforms=platforms,
        critic_reviews=critic_reviews,
        user_reviews=user_reviews,
        critic_total=critic_total,
        user_total=user_total,
        lead_userscore=lead_userscore,
        lead_user_count=lead_user_count,
        critic_negative_count=critic_negative,
        user_negative_count=user_negative,
    )


class MetacriticClient:
    def __init__(self, http: PoliteClient):
        self.http = http

    def _json(self, path: str, params: dict | None = None) -> dict:
        resp = self.http.get(BACKEND + path, params=params, headers={"Accept": "application/json"})
        return resp.json()

    def new_releases(self, limit: int = 20) -> list[ListItem]:
        payload = self._json(
            "/finder/metacritic/web",
            {
                "componentName": "new-releases-carousel",
                "componentDisplayName": "Newly Released",
                "componentType": "ProductList",
                "sortBy": "-releaseDate",
                "metaScoreMin": 1,
                "offset": 0,
                "limit": limit,
                "mcoTypeId": 13,
            },
        )
        return parse_list(payload)[0]

    def browse_new(self, offset: int, limit: int = 24) -> list[ListItem]:
        payload = self._json(
            "/finder/metacritic/web",
            {"sortBy": "-releaseDate", "productType": "games", "offset": offset, "limit": limit, "mcoTypeId": 13},
        )
        return parse_list(payload)[0]

    def game(self, slug: str) -> GameDetails:
        return parse_composer(self._json(f"/composer/metacritic/pages/games/{slug}/web"))

    def user_stats(self, slug: str, platform_slug: str) -> tuple[float | None, int | None]:
        payload = self._json(
            f"/reviews/metacritic/user/games/{slug}/platform/{platform_slug}/stats/web",
            {
                "componentName": "user-score-summary",
                "componentDisplayName": "user Score Summary",
                "componentType": "MetaScoreSummary",
            },
        )
        return parse_user_stats(payload)

    def review_list(self, kind: str, slug: str, platform_slug: str, sentiment: str = "all",
                    limit: int | None = None, offset: int = 0) -> list[Review]:
        limit = limit or (10 if kind == "critic" else 20)
        payload = self._json(
            f"/reviews/metacritic/{kind}/games/{slug}/platform/{platform_slug}/web",
            {
                "offset": offset,
                "limit": limit,
                "filterBySentiment": sentiment,
                "sort": "date",
                "componentName": f"{kind}-reviews",
                "componentDisplayName": f"{kind.title()} Reviews",
                "componentType": "ReviewList",
            },
        )
        return parse_review_list(payload, kind)[0]

    def full_game(self, slug: str, top_up_reviews: bool = True) -> GameDetails:
        game = self.game(slug)
        for p in game.platforms:
            if p.is_lead and p.userscore is not None:
                continue
            if p.is_lead and game.lead_user_count == 0:
                continue
            try:
                p.userscore, p.user_count = self.user_stats(slug, p.slug)
            except NotFound:
                p.userscore, p.user_count = None, 0
            except Exception as exc:
                log.warning("user stats %s/%s failed: %s", slug, p.slug, exc)
        if top_up_reviews:
            lead = next((p for p in game.platforms if p.is_lead), None)
            if lead:
                self._top_up(game, lead.slug, "critic")
                self._top_up(game, lead.slug, "user")
        return game

    def _top_up(self, game: GameDetails, platform_slug: str, kind: str) -> None:
        reviews = game.critic_reviews if kind == "critic" else game.user_reviews
        available = game.critic_negative_count if kind == "critic" else game.user_negative_count
        have = sum(1 for r in reviews if r.sentiment == "negative")
        if have >= 5 or available <= have:
            return
        try:
            extra = self.review_list(kind, game.slug, platform_slug, sentiment="negative")
        except Exception as exc:
            log.info("extra %s reviews for %s unavailable: %s", kind, game.slug, exc)
            return
        known = {r.quote for r in reviews}
        for r in extra:
            if r.quote not in known:
                r.sentiment = "negative"
                reviews.append(r)
                known.add(r.quote)
import logging
from dataclasses import dataclass, field
from typing import Callable

from .db import DayState
from .metacritic import ListItem

log = logging.getLogger("selection")


@dataclass
class Selection:
    items: list[tuple[ListItem, str]] = field(default_factory=list)
    state: DayState | None = None
    pages_fetched: int = 0

    @property
    def sources(self) -> str:
        seen = []
        for _, src in self.items:
            if src not in seen:
                seen.append(src)
        return ", ".join(seen)


def select_batch(
    state: DayState,
    processed: set[int],
    fetch_new_releases: Callable[[], list[ListItem]],
    fetch_browse: Callable[[int, int], list[ListItem]],
    batch_size: int = 20,
    page_size: int = 24,
    max_pages: int = 4,
) -> Selection:
    """New Releases first, then SEE ALL pages from the cursor; the cursor passes a page only once it is fully handled."""
    state = DayState(state.day, state.new_releases_done, state.browse_offset)
    sel = Selection(state=state)
    taken: set[int] = set()

    def take(items: list[ListItem], source: str) -> bool:
        for it in items:
            if it.id in processed or it.id in taken:
                continue
            if len(sel.items) >= batch_size:
                return False
            taken.add(it.id)
            sel.items.append((it, source))
        return True

    if not state.new_releases_done:
        items = fetch_new_releases()
        complete = take(items, "new-releases")
        if complete:
            state.new_releases_done = True
        if sel.items:
            return sel

    while len(sel.items) < batch_size and sel.pages_fetched < max_pages:
        items = fetch_browse(state.browse_offset, page_size)
        sel.pages_fetched += 1
        if not items:
            break
        complete = take(items, f"browse:p{state.browse_offset // page_size + 1}")
        if not complete:
            break
        state.browse_offset += page_size
    return sel

import logging
import threading
from datetime import datetime, timedelta

from .config import Settings, iso, utcnow
from .db import Database
from .llm import LLMClient, LLMError
from .metacritic import ListItem, MetacriticClient, Review
from .monitor import Monitor
from .selection import select_batch
from .similarity import GameFeatures, compute_similar
from .summarize import (
    build_letsplay_prompt,
    extractive_transcript_summary,
    reviews_hash,
    summarize_reviews,
    validate_letsplay_json,
)
from .youtube import TranscriptUnavailable, YouTubeClient, sample_transcript

log = logging.getLogger("pipeline")


class AlreadyRunning(Exception):
    pass


class Pipeline:
    def __init__(self, settings: Settings, db: Database, monitor: Monitor, metacritic: MetacriticClient,
                 youtube: YouTubeClient | None, llm: LLMClient | None):
        self.settings = settings
        self.db = db
        self.monitor = monitor
        self.mc = metacritic
        self.yt = youtube
        self.llm = llm
        self._lock = threading.Lock()

    @property
    def running(self) -> bool:
        return self._lock.locked()

    def start_background(self, trigger: str = "manual", limit: int | None = None) -> bool:
        if not self._lock.acquire(blocking=False):
            return False

        def target():
            try:
                self._run(trigger, limit)
            finally:
                self._lock.release()

        threading.Thread(target=target, name=f"pipeline-{trigger}", daemon=True).start()
        return True

    def run(self, trigger: str = "manual", limit: int | None = None) -> dict:
        if not self._lock.acquire(blocking=False):
            raise AlreadyRunning()
        try:
            return self._run(trigger, limit)
        finally:
            self._lock.release()

    def _step(self, step: str, title: str | None = None) -> None:
        detail = step if not title else f"{step}: {title}"
        self.monitor.set_worker("pipeline", "running", detail)
        self.monitor.set_progress(step=step, current=title)

    def _run(self, trigger: str, limit: int | None) -> dict:
        s = self.settings
        day = s.today()
        batch = max(1, min(limit or s.batch_size, s.batch_size))
        run_id = self.db.create_run(trigger, day)
        started = utcnow()
        self.monitor.set_progress(run_id=run_id, done=0, total=0, ok=0, failed=0, current=None,
                                  step="выбор игр", started_at=iso(started))
        self.monitor.set_worker("pipeline", "running", f"запуск #{run_id} ({trigger}): выбор игр")
        log.info("Run #%d started (%s), day %s, batch %d", run_id, trigger, day, batch)

        try:
            state = self.db.get_day_state(day)
            processed = self.db.processed_ids(day)
            sel = select_batch(
                state,
                processed,
                lambda: self.mc.new_releases(20),
                lambda offset, size: self.mc.browse_new(offset, size),
                batch_size=batch,
                page_size=s.browse_page_size,
                max_pages=s.browse_max_pages,
            )
        except Exception as exc:
            log.exception("Run #%d: selection failed", run_id)
            self.db.add_error(run_id, day, None, "selection", f"{exc.__class__.__name__}: {exc}")
            self.db.finish_run(run_id, "failed", 0, 0, 0, "", f"Не удалось получить список игр: {exc}")
            self.monitor.set_worker("pipeline", "error", f"запуск #{run_id}: не удалось получить список игр")
            self.monitor.reset_progress()
            return {"run_id": run_id, "status": "failed", "selected": 0, "ok": 0, "failed": 0}

        total = len(sel.items)
        log.info("Run #%d: selected %d games (%s), browse cursor %d -> %d", run_id, total, sel.sources or "—",
                 state.browse_offset, sel.state.browse_offset)
        self.monitor.set_progress(total=total)
        ok = failed = 0
        for i, (item, source) in enumerate(sel.items):
            self.monitor.set_progress(done=i, current=item.title)
            status = "ok"
            try:
                self.process_game(item, source, run_id, day)
                ok += 1
            except Exception as exc:
                status = "error"
                failed += 1
                log.exception("Run #%d: game %s failed", run_id, item.slug)
                self.db.add_error(run_id, day, item.slug, self.monitor.progress.get("step") or "game",
                                  f"{exc.__class__.__name__}: {exc}")
            self.db.mark_processed(day, item.id, item.slug, item.title, run_id, status, source)
            self.db.update_run_progress(run_id, total, ok, failed, sel.sources)
            self.monitor.set_progress(done=i + 1, ok=ok, failed=failed)

        self.db.save_day_state(sel.state)

        if self.settings.llm_backfill_limit and self.llm is not None:
            try:
                self._step("LLM: досчёт резюме без LLM")
                upgraded = self.backfill_llm({i.id for i, _ in sel.items}, self.settings.llm_backfill_limit)
                if upgraded:
                    log.info("Run #%d: upgraded %d fallback summaries to LLM", run_id, upgraded)
            except Exception:
                log.exception("Run #%d: LLM backfill failed", run_id)

        try:
            self._step("похожие игры")
            self.recompute_similar()
        except Exception as exc:
            log.exception("Run #%d: similarity failed", run_id)
            self.db.add_error(run_id, day, None, "similar", str(exc))

        status = "ok" if failed == 0 else ("partial" if ok else "failed")
        if total == 0:
            status = "empty"
        message = f"Обработано {ok} из {total}, ошибок {failed}"
        self.db.finish_run(run_id, status, total, ok, failed, sel.sources, message)
        elapsed = (utcnow() - started).total_seconds()
        log.info("Run #%d finished: %s in %.0f s", run_id, message, elapsed)
        self.monitor.set_worker("pipeline", "idle", f"последний запуск #{run_id}: {message.lower()}")
        self.monitor.reset_progress()
        return {"run_id": run_id, "status": status, "selected": total, "ok": ok, "failed": failed,
                "sources": sel.sources, "seconds": round(elapsed)}

    def process_game(self, item: ListItem, source: str, run_id: int, day: str) -> None:
        self._step("Metacritic: карточка и оценки", item.title)
        game = self.mc.full_game(item.slug)
        if not game.cover_url:
            game.cover_url = item.cover_url
        prev = self.db.get_previous(game.id) or {}
        is_new = self.db.upsert_game(game, source)
        log.info("%s %s: %d platforms, metascore %s, userscore %s, %d+%d reviews",
                 "Added" if is_new else "Updated", game.slug, len(game.platforms), game.metascore,
                 game.userscore, len(game.critic_reviews), len(game.user_reviews))

        for kind, reviews, total, column in (
            ("critic", game.critic_reviews, game.critic_total, "critic_summary"),
            ("user", game.user_reviews, game.user_total, "user_summary"),
        ):
            old = prev.get(column)
            if (old and old.get("reviews_hash") == reviews_hash(reviews)
                    and old.get("method") in ("llm", "none")):
                old["review_count"] = total
                self.db.set_json(game.id, column, old)
                continue
            self._step("резюме критиков" if kind == "critic" else "резюме игроков", game.title)
            summary = summarize_reviews(self.llm, game.title, kind, reviews, total)
            self.db.set_json(game.id, column, summary)
            if summary.get("error"):
                self.db.add_error(run_id, day, game.slug, f"llm:{kind}", summary["error"])

        if self.yt is None:
            return
        old_lp = prev.get("letsplay")
        if self._letsplay_fresh(old_lp):
            return
        self._step("YouTube: поиск летсплея", game.title)
        try:
            letsplay = self.find_letsplay(game.title)
        except Exception as exc:
            log.warning("Let's play for %s failed: %s", game.slug, exc)
            self.db.add_error(run_id, day, game.slug, "youtube", f"{exc.__class__.__name__}: {exc}")
            letsplay = {"status": "error", "method": "none", "note": f"Ошибка при поиске летсплея: {exc}",
                        "updated_at": iso(utcnow())}
            if old_lp and old_lp.get("video"):
                old_lp["last_error"] = letsplay["note"]
                letsplay = old_lp
        self.db.set_json(game.id, "letsplay", letsplay)

    def _letsplay_fresh(self, old: dict | None) -> bool:
        if not old or old.get("method") != "llm-transcript":
            return False
        try:
            updated = datetime.fromisoformat(old["updated_at"])
        except (KeyError, ValueError, TypeError):
            return False
        return utcnow() - updated < timedelta(days=self.settings.letsplay_refresh_days)

    def find_letsplay(self, title: str) -> dict:
        now = iso(utcnow())
        candidates = self.yt.find_letsplays(title)
        top = [c.to_dict() for c in candidates[:5]]
        if not candidates:
            return {"status": "no_video", "method": "none", "candidates": [], "updated_at": now,
                    "note": "На YouTube не нашлось подходящих летсплеев длиннее 10 минут"}
        checked = []
        for cand in candidates[: self.settings.youtube_max_candidates]:
            self._step("YouTube: расшифровка", f"{title} / {cand.video_id}")
            try:
                text, lang = self.yt.transcript(cand.video_id)
            except TranscriptUnavailable as exc:
                checked.append({"video_id": cand.video_id, "reason": str(exc)})
                log.info("No transcript for %s (%s): %s", cand.video_id, title, exc)
                continue
            self._refine(cand)
            self._step("LLM: заключение по летсплею", title)
            result, method, error = self._conclude(title, cand, text, "transcript")
            if result is None:
                result, method = extractive_transcript_summary(text), "extractive-transcript"
            return {"status": "ok", "method": method, "video": cand.to_dict(), "transcript_chars": len(text),
                    "transcript_lang": lang, "transcript_excerpt": sample_transcript(text, 6000),
                    "checked": checked, "candidates": top, "updated_at": now, "error": error, **result}

        best = candidates[0]
        self._refine(best)
        reasons = "; ".join(f"{c['video_id']}: {c['reason']}" for c in checked)
        note = f"Расшифровка недоступна ({reasons})" if reasons else "Расшифровка недоступна"
        if best.description:
            text = f"Название: {best.title}\nОписание: {best.description[:3000]}"
            result, method, error = self._conclude(title, best, text, "description")
            if result is None:
                result = {"summary": best.description[:600], "pros": [], "cons": [], "verdict": ""}
                method = "description"
            return {"status": "no_transcript", "method": method, "video": best.to_dict(), "checked": checked,
                    "candidates": top, "updated_at": now, "note": note, "error": error, **result}
        return {"status": "no_transcript", "method": "none", "video": best.to_dict(), "checked": checked,
                "candidates": top, "updated_at": now, "note": note}

    def _refine(self, cand) -> None:
        try:
            details = self.yt.watch_details(cand.video_id)
        except Exception as exc:
            log.info("Watch page for %s unavailable: %s", cand.video_id, exc)
            return
        if not details:
            return
        cand.title = details.get("title") or cand.title
        cand.views = details.get("views") or cand.views
        cand.length_seconds = details.get("length_seconds") or cand.length_seconds
        cand.channel = details.get("channel") or cand.channel
        cand.description = details.get("description") or cand.description

    def _conclude(self, title: str, cand, text: str, source: str):
        if self.llm is None:
            return None, None, "LLM отключена"
        try:
            result = self.llm.ask_json(
                lambda budget: build_letsplay_prompt(title, cand.title, cand.channel, text, source, budget),
                validate_letsplay_json)
            return result, f"llm-{source}", None
        except LLMError as exc:
            log.warning("LLM let's play conclusion for %s failed: %s", title, exc)
            return None, None, str(exc)[:200]

    def backfill_llm(self, skip_ids: set[int], limit: int) -> int:
        upgraded = 0
        for g in self.db.games_with_fallbacks(limit * 3):
            if g["id"] in skip_ids:
                continue
            for kind, column in (("critic", "critic_summary"), ("user", "user_summary")):
                old = g[column]
                if not old or old.get("method") != "extractive":
                    continue
                reviews = [Review(**r) for r in g[f"{kind}_reviews"]]
                new = summarize_reviews(self.llm, g["title"], kind, reviews, old.get("review_count") or len(reviews))
                if new.get("method") != "llm":
                    return upgraded
                self.db.set_json(g["id"], column, new)
                upgraded += 1
                if upgraded >= limit:
                    return upgraded
            lp = g["letsplay"]
            if lp and lp.get("method") == "extractive-transcript" and lp.get("transcript_excerpt") and lp.get("video"):
                from .youtube import VideoCandidate

                v = lp["video"]
                cand = VideoCandidate(video_id=v["video_id"], title=v.get("title") or "", channel=v.get("channel"))
                result, method, error = self._conclude(g["title"], cand, lp["transcript_excerpt"], "transcript")
                if result is None:
                    return upgraded
                lp.update(result, method=method, error=None, updated_at=iso(utcnow()))
                self.db.set_json(g["id"], "letsplay", lp)
                upgraded += 1
                if upgraded >= limit:
                    return upgraded
        return upgraded

    def recompute_similar(self) -> int:
        feats = [GameFeatures(**f) for f in self.db.all_features()]
        mapping = compute_similar(feats, top_n=self.settings.similar_top_n)
        self.db.set_similar_bulk(mapping)
        return len(mapping)
