from .config import Settings, utcnow
from .db import Database
from .monitor import Monitor
from .pipeline import AlreadyRunning, Pipeline

log = logging.getLogger("scheduler")


def initial_next_run(settings: Settings, db: Database, now: datetime | None = None) -> datetime:
    now = now or utcnow()
    soon = now + timedelta(seconds=settings.startup_delay_seconds)
    interval = timedelta(minutes=settings.run_interval_minutes)
    last = db.last_run()
    if last:
        try:
            last_start = datetime.fromisoformat(last["started_at"])
        except (TypeError, ValueError):
            last_start = None
        if last_start:
            return max(soon, last_start + interval)
    if db.count_games() == 0:
        return soon
    return now + interval


class Scheduler:
    def __init__(self, settings: Settings, db: Database, pipeline: Pipeline, monitor: Monitor):
        self.settings = settings
        self.db = db
        self.pipeline = pipeline
        self.monitor = monitor
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self.next_run: datetime | None = None

    def start(self) -> None:
        if not self.settings.scheduler_enabled:
            self.monitor.set_worker("scheduler", "off", "планировщик выключен (SCHEDULER_ENABLED=0)")
            return
        self._thread = threading.Thread(target=self._loop, name="scheduler", daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread:
            self._thread.join(timeout=5)

    def _set_next(self, when: datetime) -> None:
        self.next_run = when
        self.monitor.set_next_run(when)
        local = when.astimezone(self.settings.day_tz).strftime("%H:%M:%S")
        self.monitor.set_worker("scheduler", "waiting", f"следующий запуск в {local}")

    def _loop(self) -> None:
        interval = timedelta(minutes=self.settings.run_interval_minutes)
        self._set_next(initial_next_run(self.settings, self.db))
        log.info("Scheduler started, next run at %s", self.next_run.isoformat(timespec="seconds"))
        while not self._stop.is_set():
            remaining = (self.next_run - utcnow()).total_seconds()
            if remaining > 0:
                self._stop.wait(min(remaining, 30))
                continue
            started = utcnow()
            if self.pipeline.running:
                log.info("Scheduled run skipped: a run is already in progress")
                self._set_next(started + interval)
                continue
            self.monitor.set_worker("scheduler", "running", "плановый запуск обработки")
            try:
                self.pipeline.run("schedule")
            except AlreadyRunning:
                log.info("Scheduled run skipped: a run is already in progress")
            except Exception:
                log.exception("Scheduled run crashed")
            self._set_next(started + interval)
        self.monitor.set_worker("scheduler", "off", "остановлен")
import logging
import threading
import time
from collections import deque

from .config import iso, utcnow

WORKER_TITLES = {
    "scheduler": "Планировщик",
    "pipeline": "Обработчик игр",
    "metacritic": "Metacritic",
    "youtube": "YouTube",
    "llm": "LLM",
}


class Monitor:
    def __init__(self, log_size: int = 400):
        self._lock = threading.Lock()
        self.version = 0
        self._log: deque = deque(maxlen=log_size)
        self._log_seq = 0
        self.workers: dict[str, dict] = {
            name: {"name": name, "title": title, "status": "idle", "detail": "", "updated_at": iso(utcnow())}
            for name, title in WORKER_TITLES.items()
        }
        self.counters = {
            "metacritic_ok": 0, "metacritic_failed": 0,
            "youtube_ok": 0, "youtube_failed": 0,
            "llm_ok": 0, "llm_failed": 0, "llm_last_latency": None,
        }
        self.progress = {"run_id": None, "done": 0, "total": 0, "ok": 0, "failed": 0, "current": None,
                         "step": None, "started_at": None}
        self.next_run_at: str | None = None
        self.started_at = iso(utcnow())

    def _bump(self) -> None:
        self.version += 1

    def set_worker(self, name: str, status: str, detail: str = "") -> None:
        with self._lock:
            w = self.workers[name]
            w.update(status=status, detail=detail, updated_at=iso(utcnow()))
            self._bump()

    def set_progress(self, **kwargs) -> None:
        with self._lock:
            self.progress.update(kwargs)
            self._bump()

    def reset_progress(self) -> None:
        with self._lock:
            self.progress = {"run_id": None, "done": 0, "total": 0, "ok": 0, "failed": 0, "current": None,
                             "step": None, "started_at": None}
            self._bump()

    def set_next_run(self, when) -> None:
        with self._lock:
            self.next_run_at = iso(when) if when else None
            self._bump()

    def http_event(self, host: str, ok: bool) -> None:
        key = "youtube" if "youtube" in host else "metacritic" if "metacritic" in host else None
        if not key:
            return
        with self._lock:
            self.counters[f"{key}_{'ok' if ok else 'failed'}"] += 1
            w = self.workers[key]
            w["status"] = "ok" if ok else "error"
            w["detail"] = f"запросов: {self.counters[key + '_ok']} успешных, {self.counters[key + '_failed']} с ошибкой"
            w["updated_at"] = iso(utcnow())
            self._bump()

    def llm_event(self, ok: bool, latency: float) -> None:
        with self._lock:
            self.counters["llm_ok" if ok else "llm_failed"] += 1
            self.counters["llm_last_latency"] = round(latency, 1)
            w = self.workers["llm"]
            w["status"] = "ok" if ok else "error"
            w["detail"] = (f"вызовов: {self.counters['llm_ok']} успешных, {self.counters['llm_failed']} с ошибкой; "
                           f"последний ответ за {latency:.1f} с")
            w["updated_at"] = iso(utcnow())
            self._bump()

    def add_log(self, record: logging.LogRecord, message: str) -> None:
        with self._lock:
            self._log_seq += 1
            self._log.append({
                "id": self._log_seq,
                "ts": time.strftime("%H:%M:%S", time.localtime(record.created)),
                "level": record.levelname,
                "logger": record.name,
                "message": message,
            })
            self._bump()

    def logs_since(self, last_id: int = 0, limit: int = 200) -> list[dict]:
        with self._lock:
            items = [e for e in self._log if e["id"] > last_id]
        return items[-limit:]

    def snapshot(self) -> dict:
        with self._lock:
            return {
                "version": self.version,
                "workers": [dict(w) for w in self.workers.values()],
                "counters": dict(self.counters),
                "progress": dict(self.progress),
                "next_run_at": self.next_run_at,
                "started_at": self.started_at,
            }


class MonitorLogHandler(logging.Handler):
    def __init__(self, monitor: Monitor):
        super().__init__(level=logging.INFO)
        self.monitor = monitor

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.monitor.add_log(record, record.getMessage())
        except Exception:
            pass


